window.HOEREN_TESTS[62] = {"id":"in-der-autowerkstatt","name":"In der Autowerkstatt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Werkstatt Müller. Ihr Auto ist fertig — aber es war nicht nur die Bremse, sondern auch der Reifen war kaputt. Deshalb kostet es mehr als gedacht, insgesamt 450 Euro. Sie können den Wagen ab 16 Uhr abholen. Bitte bringen Sie den Schlüssel mit. Tschüs!","gender":"m","q":"Was war alles kaputt?","opts":["Nur die Bremse.","Nur der Reifen.","Bremse und Reifen."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Mein Auto macht ein komisches Geräusch beim Bremsen. Beim Starten ist alles normal, und beim Parken auch, nur beim Bremsen kracht es. Ich traue mich nicht mehr zu fahren. Kennst du eine gute Werkstatt? Nicht zu teuer, aber ehrlich. Die letzte hat mich abgezockt. Ruf mich an, ich brauche bald einen Termin. Danke!","gender":"m","q":"Wann macht das Auto das Geräusch?","opts":["Beim Starten.","Beim Bremsen.","Beim Parken."],"correct":1},{"transcript":"Achtung Kunden: Unsere Werkstatt macht vom 1. bis 14. August Betriebsferien. In dringenden Fällen — Panne oder Unfall — rufen Sie den Notdienst an, die Nummer steht an der Tür. Reifen wechseln geht vorher noch, nur in den Ferien nicht. Normale Termine wie Inspektion bitte erst ab dem 15. August. Wir wünschen schöne Ferien!","gender":"f","q":"Was kann man während der Ferien machen?","opts":["Den Notdienst anrufen.","Reifen wechseln lassen.","Eine normale Inspektion."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, mein Auto ist in der Werkstatt, dauert zwei Tage. Nicht einen Tag und keine Woche, genau zwei Tage. Kannst du mich morgen zur Arbeit fahren? Oder soll ich den Bus nehmen? Die Werkstatt bietet auch einen Ersatzwagen, aber der kostet extra. Sag mir Bescheid, was einfacher ist. Danke dir!","gender":"f","q":"Wie lange dauert die Reparatur?","opts":["Eine Woche.","Einen Tag.","Zwei Tage."],"correct":2},{"transcript":"Liebe Kunden: Ab Oktober bieten wir den Reifenwechsel im Paket an. Wechsel plus Einlagerung der Sommerreifen kostet zusammen 80 Euro. Nur der Wechsel allein 40 Euro. Keine 120 Euro, nur 80 Euro mit Einlagerung. Bitte buchen Sie früh einen Termin — im Herbst ist immer viel los. Wir freuen uns auf Sie!","gender":"m","q":"Was kostet das Paket mit Einlagerung?","opts":["80 Euro.","120 Euro.","40 Euro."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat welches Problem? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Werkstatt hat morgen früh noch einen freien Platz."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du anrufst. Mein Wagen macht schon seit Tagen Ärger."},{"speaker":"Lukas","gender":"m","text":"Bei mir ist die Batterie leer. Der Wagen bleibt seit gestern einfach still."},{"speaker":"Lisa","gender":"f","text":"Bei mir ist ein platter Reifen. Ich bin heute mit dem Bus zur Arbeit gekommen."},{"speaker":"Lukas","gender":"m","text":"Ist bei jemandem der Scheibenwischer kaputt?"},{"speaker":"Lisa","gender":"f","text":"Nein. Der Scheibenwischer ist bei uns nicht kaputt."},{"speaker":"Lukas","gender":"m","text":"Tom hört beim Bremsen ein lautes Geräusch vorn am Rad."},{"speaker":"Lisa","gender":"f","text":"Bei Tom ist die Bremse defekt. Er lässt den Wagen erst einmal stehen."},{"speaker":"Lukas","gender":"m","text":"Sara findet morgens dunkle Flecken auf dem Boden vor der Garage."},{"speaker":"Lisa","gender":"f","text":"Sara verliert Öl. Der Fleck unter dem Wagen wird jeden Tag größer."},{"speaker":"Lukas","gender":"m","text":"Ist der Auspuff bei jemandem von uns defekt?"},{"speaker":"Lisa","gender":"f","text":"Nein. Der Auspuff ist nicht defekt und klingt überall normal."},{"speaker":"Lukas","gender":"m","text":"Tim schwitzt schon bei einer kurzen Fahrt durch die Stadt."},{"speaker":"Lisa","gender":"f","text":"Bei Tim ist die Klimaanlage kaputt. Warme Luft kommt aus der mittleren Düse."},{"speaker":"Lukas","gender":"m","text":"Dann bringe ich meinen Wagen morgen als Erster hin."},{"speaker":"Lisa","gender":"f","text":"Ich komme direkt nach dir und fahre mit dem Rad."}],"options":[{"letter":"a","text":"Scheibenwischer kaputt"},{"letter":"b","text":"Licht funktioniert nicht"},{"letter":"c","text":"Platter Reifen"},{"letter":"d","text":"Motor springt nicht an"},{"letter":"e","text":"Verliert Öl"},{"letter":"f","text":"Bremse defekt"},{"letter":"g","text":"Batterie leer"},{"letter":"h","text":"Auspuff defekt"},{"letter":"i","text":"Klimaanlage kaputt"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"c"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Wann ist mein Auto fertig? Um 12 Uhr?"},{"speaker":"Mechaniker","gender":"m","text":"Heute Nachmittag um 15 Uhr. Um 12 Uhr schaffen wir es nicht."},{"speaker":"Kundin","gender":"f","text":"Schade! Geht es nicht früher? Morgen wäre zu spät für mich."},{"speaker":"Mechaniker","gender":"m","text":"Nein, früher geht nicht. Wir brauchen das Ersatzteil, es kommt um zwei."},{"speaker":"Kundin","gender":"f","text":"Gut, dann komme ich um 15 Uhr. Bis später!"}],"q":"Wann ist das Auto fertig?","opts":["Um 15 Uhr.","Um 12 Uhr.","Morgen."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag! Was kostet die Inspektion? Die große?"},{"speaker":"Mechanikerin","gender":"f","text":"Die kleine kostet 120 Euro, die große 250 Euro. 200 Euro gibt es nicht."},{"speaker":"Mann","gender":"m","text":"250 Euro, viel Geld! Welche brauche ich denn wirklich?"},{"speaker":"Mechanikerin","gender":"f","text":"Bei Ihrem alten Auto die große, sicher."},{"speaker":"Mann","gender":"m","text":"Na gut, dann die große für 250 Euro. Wann kann ich kommen?"}],"q":"Was kostet die große Inspektion?","opts":["120 Euro.","200 Euro.","250 Euro."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Mein Auto zieht nach rechts. Ist es der Motor oder die Bremse?"},{"speaker":"Mechaniker","gender":"m","text":"Weder Motor noch Bremse. Die Spur muss eingestellt werden."},{"speaker":"Kunde","gender":"m","text":"Ist das schlimm? Teuer?"},{"speaker":"Mechaniker","gender":"m","text":"Nein, in einer Stunde erledigt. Kostet nur 50 Euro."},{"speaker":"Kunde","gender":"m","text":"Gut, dann machen Sie die Spur, bitte. Ich warte hier, im Café."}],"q":"Was muss gemacht werden?","opts":["Die Bremse reparieren.","Den Motor wechseln.","Die Spur einstellen."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Kann ich einen Ersatzwagen bekommen? Was kostet er pro Tag?"},{"speaker":"Mechaniker","gender":"m","text":"Ja, einen kleinen für 25 Euro am Tag. 15 Euro gibt es leider nicht."},{"speaker":"Frau","gender":"f","text":"Und einen größeren? Für 35 Euro vielleicht?"},{"speaker":"Mechaniker","gender":"m","text":"Nein, das ist schon der günstigste. Größere haben wir nicht frei."},{"speaker":"Frau","gender":"f","text":"Gut, dann den kleinen für 25 Euro, bitte!"}],"q":"Was kostet der Ersatzwagen pro Tag?","opts":["15 Euro.","25 Euro.","35 Euro."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Macht ihr auch den TÜV? Wann kommt der Prüfer?"},{"speaker":"Mechanikerin","gender":"f","text":"Ja, der Prüfer kommt mittwochs. Nicht montags und nicht freitags."},{"speaker":"Kunde","gender":"m","text":"Mittwoch passt mir nicht. Brauche ich einen Termin?"},{"speaker":"Mechanikerin","gender":"f","text":"Ja, unbedingt. Ich trage Sie für nächsten Mittwoch ein."},{"speaker":"Kunde","gender":"m","text":"Gut, nächsten Mittwoch! Um wie viel Uhr?"},{"speaker":"Mechanikerin","gender":"f","text":"Um 10 Uhr. Bringen Sie die Papiere mit!"}],"q":"An welchem Tag kommt der TÜV-Prüfer?","opts":["Montags.","Mittwochs.","Freitags."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Wolf, einem Kfz-Meister. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Wolf, wie lange arbeiten Sie schon als Mechaniker? Schon lange, oder?"},{"speaker":"Wolf","gender":"m","text":"Schon seit zwanzig Jahren, ja. Ich repariere jeden Tag Autos, alles Mögliche. Die Arbeit macht mir Spaß, immer noch. Ich lerne jeden Tag etwas Neues. Das ist schön."},{"speaker":"Reporterin","gender":"f","text":"Was reparieren Sie am häufigsten? Bremsen oder Motor?"},{"speaker":"Wolf","gender":"m","text":"Meistens Bremsen und Reifen, das ist Standard. Fenster fast nie, vielleicht zweimal im Jahr. Im Winter sind oft die Batterien leer. Das ist normal."},{"speaker":"Reporterin","gender":"f","text":"Müssen die Kunden lange warten?"},{"speaker":"Wolf","gender":"m","text":"Manchmal ja, einen Tag oder zwei. Aber bei einem Notfall helfe ich sofort, da warte ich nicht. Sicherheit zuerst. Das geht schnell."},{"speaker":"Reporterin","gender":"f","text":"Wie können die Kunden Geld sparen?"},{"speaker":"Wolf","gender":"m","text":"Sie sollen früh kommen, nicht erst spät. Ein kleines Problem ist billig, ein großes ist teuer und dauert lange. Das sage ich immer."},{"speaker":"Reporterin","gender":"f","text":"Was wünschen Sie sich von den Kunden? Haben Sie Tipps?"},{"speaker":"Wolf","gender":"m","text":"Dass sie mir vertrauen. Ich zeige ihnen immer die kaputten Teile, ganz offen. Ich bin ehrlich, das ist mein Prinzip, seit zwanzig Jahren."}],"items":[{"q":"Herr Wolf arbeitet seit zwanzig Jahren als Mechaniker.","correct":"ja"},{"q":"Er repariert am häufigsten die Fenster.","correct":"nein"},{"q":"Bei einem Notfall hilft er sofort.","correct":"ja"},{"q":"Er rät, erst spät in die Werkstatt zu kommen.","correct":"nein"},{"q":"Er zeigt den Kunden die kaputten Teile.","correct":"ja"}]}]};
